// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes memory _data) public {
        // Bound _data length to avoid excessive gas, but keep the rule general.
        vm.assume(_data.length <= 100);

        // Deploy a simple receiver contract that logs the data it receives.
        Receiver receiver = new Receiver();

        // Call forward on C with the receiver and _data.
        c.forward(address(receiver), _data);

        // The rule: receiver.lastData must equal the original _data.
        // The reference C will pass; the mutant that always calls with '' will fail.
        assertTrue(keccak256(receiver.lastData()) == keccak256(_data));
    }
}

contract Receiver {
    bytes public lastData;

    receive() external payable {
        // Note: the call is with empty calldata; we cannot receive actual _data this way.
        // This contract is just a placeholder for the property; the actual test should use a different approach.
    }

    fallback() external payable {
        lastData = msg.data;
    }
}

